// Script di installazione: scrive i file aggiornati nella cartella del progetto.
// Esegui con: node applica-modifiche.js  (dalla cartella radice di sito-viaggi)
// Non tocca git: dopo, fai tu add/commit/push come al solito.
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));

const file = {};

file['src/components/MappaWandex.jsx'] = '';
file['src/pages/Statistiche.jsx'] = '';
file['src/pages/Statistiche.css'] = '';
file['src/pages/Amici.jsx'] = '';
file['src/pages/Home.jsx'] = '';

for (const [percorso, base64Contenuto] of Object.entries(file)) {
  const percorsoAssoluto = path.join(__dirname, percorso);
  fs.mkdirSync(path.dirname(percorsoAssoluto), { recursive: true });
  fs.writeFileSync(percorsoAssoluto, Buffer.from(base64Contenuto, 'base64'));
  console.log('Scritto:', percorso);
}

console.log('\nFatto. Ora puoi controllare i file, poi git add / commit / push.');